import static org.mockito.Mockito.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class LayersDeriveTest extends BaseLayersTest
{
	@Value
	public static class Case
	{
		// setup
		int[] equipIds;
		// output
		Map<KitType, SlotInfo> items;
		Map<KitType, Integer> kits;
		JawIcon icon;
	}

	private PlayerComposition composition;

	private final int hairColor = HairColor.AQUA.getColorId();
	private final int torsoColor = ClothingColor.BLACK.getColorId(ColorType.TORSO);
	private final int legsColor = ClothingColor.WHITE.getColorId(ColorType.LEGS);
	private final int bootsColor = BootsColor.BROWN.getColorId();
	private final int skinColor = SkinColor.CYAN.getColorId();
	private final int[] colors = {hairColor, torsoColor, legsColor, bootsColor, skinColor};

	public static Stream<Case> provideCases()
	{
		return Stream.of(
			new Case(
				TestData.comp1,
				ImmutableMap.of(
					KitType.CAPE, TestData.blueCape,
					KitType.WEAPON, TestData.white2hSword
				),
				new ImmutableMap.Builder<KitType, Integer>()
					.put(KitType.TORSO, TestData.plainTorso.getKitId())
					.put(KitType.ARMS, TestData.thinStripeArms.getKitId())
					.put(KitType.LEGS, TestData.flaresLegs.getKitId())
					.put(KitType.HAIR, TestData.curlsHair.getKitId())
					.put(KitType.HANDS, TestData.bracersHands.getKitId())
					.put(KitType.BOOTS, TestData.smallBoots.getKitId())
					.put(KitType.JAW, TestData.daliJaw.getKitId())
					.build(),
				null),
			new Case(
				TestData.comp2,
				new ImmutableMap.Builder<KitType, SlotInfo>()
					.put(KitType.HEAD, TestData.ironFullHelm)
					.put(KitType.AMULET, TestData.camulet)
					.put(KitType.WEAPON, TestData.blackMace)
					.put(KitType.TORSO, TestData.bronzePlatebody)
					.put(KitType.SHIELD, TestData.gildedKiteshield)
					.put(KitType.LEGS, TestData.mimeLegs)
					.put(KitType.HANDS, TestData.leatherGloves)
					.put(KitType.BOOTS, TestData.pinkBoots)
					.build(),
				ImmutableMap.of(),
				JawIcon.BA_DEFENDER)
		);
	}

	@ParameterizedTest
	@MethodSource("provideCases")
	void testEquipment(Case c)
	{
		mockComposition(c.equipIds);
		layers.deriveNonEquipment(composition, 0);
		layers.deriveEquipment(composition);
		ModelInfo realModels = layers.getRealModels();
		assertEquals(c.items, realModels.getItems().getAll());
		assertEquals(c.kits, realModels.getKits().getAll());
		assertEquals(c.icon, realModels.getIcon());
		resetData();
	}

	@Test
	void testColors()
	{
		// equipment ids are irrelevant
		mockComposition(new int[12]);
		layers.deriveNonEquipment(composition, 0);
		Map<ColorType, Integer> expected = Arrays.stream(ColorType.values())
			.collect(Collectors.toMap(c -> c, c -> colors[c.ordinal()]));
		assertEquals(expected, layers.getRealModels().getColors().getAll());
	}

	private void mockComposition(int[] equipmentIds)
	{
		composition = mock(PlayerComposition.class);
		// behavior is equivalent for masc/fem
		when(composition.getGender()).thenReturn(0);
		when(composition.getColors()).thenReturn(colors);
		when(composition.getEquipmentIds()).thenReturn(equipmentIds);
		when(composition.getEquipmentId(any()))
			.thenAnswer(input -> {
					KitType slot = input.getArgument(0);
					return equipmentIds[slot.getIndex()];
				}
			);
	}
}

package eq.uirs.fashionscape.core;

import com.google.inject.Inject;
import eq.uirs.fashionscape.base.BaseLayersTest;
import eq.uirs.fashionscape.data.color.ColorType;
import net.runelite.api.kit.KitType;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import org.junit.jupiter.api.Test;

public class HistoryTest extends BaseLayersTest
{
	@Inject
	private History history;

	private Diff colorDiff(int from, int to)
	{
		return Diff.ofColor(ColorType.HAIR, from, to);
	}

	@Test
	void emptyAppendIgnored()
	{
		history.append(Diff.empty());
		assertEquals(0, history.undoSize());
	}

	@Test
	void duplicateAppendIgnored()
	{
		history.append(colorDiff(0, 1));
		history.append(colorDiff(0, 1));
		assertEquals(1, history.undoSize());
	}

	@Test
	void undoingThenAppending()
	{
		history.append(colorDiff(0, 1));
		history.undo();
		assertEquals(0, history.undoSize());
		assertEquals(1, history.redoSize());
		// appending should clear the redo queue
		history.append(colorDiff(2, 3));
		assertEquals(1, history.undoSize());
		assertEquals(0, history.redoSize());
	}

	@Test
	void historyReachesMaxSize()
	{
		for (int i = 0; i < 12; i++)
		{
			history.append(colorDiff(i, i + 1));
		}
		assertEquals(10, history.undoSize());
	}

	@Test
	void modifyingHistoryChangesLayers()
	{
		Diff diff = layers.set(KitType.LEGS, TestData.mimeLegs, false);
		history.append(diff);
		assertEquals(TestData.mimeLegs, layers.getVirtualModels().getItems().get(KitType.LEGS));

		history.undo();
		assertNull(layers.getVirtualModels().getItems().get(KitType.LEGS));
		assertEquals(0, history.undoSize());
		assertEquals(1, history.redoSize());

		history.redo();
		assertEquals(TestData.mimeLegs, layers.getVirtualModels().getItems().get(KitType.LEGS));
		assertEquals(1, history.undoSize());
		assertEquals(0, history.redoSize());
	}
}

package eq.uirs.fashionscape.core;

import com.google.common.collect.ImmutableMap;
import eq.uirs.fashionscape.base.BaseLayersTest;
import java.util.HashMap;
import java.util.Map;
import java.util.stream.Stream;
import lombok.Value;
import net.runelite.api.kit.KitType;
import static org.junit.jupiter.api.Assertions.assertEquals;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;

public class LayersDiffTest extends BaseLayersTest
{
	@Value
	public static class Case
	{
		// setup
		Map<KitType, Integer> kits;
		Map<KitType, SlotInfo> items;
		// input
		KitType slot;
		SlotInfo info;
		// output
		Map<KitType, SlotInfo> outSlots;
	}

	public static Stream<Case> provideCases()
	{
		return Stream.of(
			// no change
			new Case(
				ImmutableMap.of(),
				ImmutableMap.of(),
				KitType.AMULET,
				null,
				ImmutableMap.of()),
			// simple amulet add
			new Case(
				ImmutableMap.of(),
				ImmutableMap.of(),
				KitType.AMULET,
				TestData.camulet,
				ImmutableMap.of()),
			// simple helm replace
			new Case(
				ImmutableMap.of(),
				ImmutableMap.of(KitType.HEAD, TestData.faceMask),
				KitType.HEAD,
				TestData.redPartyHat,
				ImmutableMap.of(KitType.HEAD, TestData.faceMask)),
			// boot item replaces kit
			new Case(
				ImmutableMap.of(KitType.BOOTS, TestData.smallBoots.getKitId()),
				ImmutableMap.of(),
				KitType.BOOTS,
				TestData.pinkBoots,
				ImmutableMap.of(KitType.BOOTS, TestData.smallBoots)),
			// torso kit replaces item (legs are unaffected)
			new Case(
				ImmutableMap.of(),
				ImmutableMap.of(KitType.TORSO, TestData.bronzePlatebody,
					KitType.LEGS, TestData.mimeLegs),
				KitType.TORSO,
				TestData.plainTorso,
				ImmutableMap.of(KitType.TORSO, TestData.bronzePlatebody)),
			// torso item replaces torso+arms kits
			new Case(
				ImmutableMap.of(
					KitType.TORSO, TestData.plainTorso.getKitId(),
					KitType.ARMS, TestData.thinStripeArms.getKitId()
				),
				ImmutableMap.of(),
				KitType.TORSO,
				TestData.bronzePlatebody,
				ImmutableMap.of(KitType.TORSO, TestData.plainTorso,
					KitType.ARMS, TestData.thinStripeArms)),
			// shield replaces 2h weapon
			new Case(
				ImmutableMap.of(),
				ImmutableMap.of(KitType.WEAPON, TestData.white2hSword),
				KitType.SHIELD,
				TestData.gildedKiteshield,
				ImmutableMap.of(KitType.WEAPON, TestData.white2hSword)),
			// weapon replaces shield and hands kit
			new Case(
				ImmutableMap.of(KitType.HANDS, TestData.bracersHands.getKitId()),
				ImmutableMap.of(KitType.SHIELD, TestData.gildedKiteshield),
				KitType.WEAPON,
				TestData.beachBoxingGloves,
				ImmutableMap.of(KitType.SHIELD, TestData.gildedKiteshield,
					KitType.HANDS, TestData.bracersHands)),
			// cloak replaces hair kit
			new Case(
				ImmutableMap.of(KitType.HAIR, TestData.curlsHair.getKitId()),
				ImmutableMap.of(),
				KitType.CAPE,
				TestData.hoodedCloak,
				ImmutableMap.of(KitType.HAIR, TestData.curlsHair)),
			// torso item replaces weapon (since both hide hands) and arms kit
			new Case(
				ImmutableMap.of(KitType.ARMS, TestData.thinStripeArms.getKitId()),
				ImmutableMap.of(KitType.WEAPON, TestData.beachBoxingGloves),
				KitType.TORSO,
				TestData.plagueJacket,
				ImmutableMap.of(KitType.WEAPON, TestData.beachBoxingGloves,
					KitType.ARMS, TestData.thinStripeArms))
		);
	}

	@ParameterizedTest
	@MethodSource("provideCases")
	void diffs(Case c)
	{
		setKitsOnModels(c.kits, layers.getVirtualModels());
		layers.getVirtualModels().getItems().putAll(c.items);
		Diff d = layers.set(c.slot, c.info, false);
		Map<KitType, SlotInfo> inSlots = new HashMap<>();
		if (c.info != null)
		{
			inSlots.put(c.slot, c.info);
		}
		assertEquals(Diff.ofSlots(c.outSlots, inSlots), d);
		resetData();
	}
}

