package eq.uirs.fashionscape.core;

import eq.uirs.fashionscape.core.event.KnownKitChanged;
import eq.uirs.fashionscape.data.kit.ArmsKit;
import eq.uirs.fashionscape.data.kit.BootsKit;
import eq.uirs.fashionscape.data.kit.HairKit;
import eq.uirs.fashionscape.data.kit.HandsKit;
import eq.uirs.fashionscape.data.kit.JawKit;
import eq.uirs.fashionscape.data.kit.LegsKit;
import eq.uirs.fashionscape.data.kit.TorsoKit;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.kit.KitType;
import net.runelite.client.eventbus.EventBus;

// when real player kit info is not known, default values should be shown, otherwise models will look broken
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = {@Inject})
public class Fallbacks
{
	// body type A in-game
	private static final Map<KitType, Integer> MASC_KITS = new HashMap<>();
	// body type B in-game
	private static final Map<KitType, Integer> FEM_KITS = new HashMap<>();

	private final EventBus eventBus;

	static
	{
		MASC_KITS.put(KitType.HAIR, HairKit.BALD.getKitId(0));
		MASC_KITS.put(KitType.JAW, JawKit.GOATEE.getKitId(0));
		MASC_KITS.put(KitType.TORSO, TorsoKit.PLAIN.getKitId(0));
		MASC_KITS.put(KitType.ARMS, ArmsKit.REGULAR.getKitId(0));
		MASC_KITS.put(KitType.LEGS, LegsKit.PLAIN_L.getKitId(0));
		MASC_KITS.put(KitType.HANDS, HandsKit.PLAIN_H.getKitId(0));
		MASC_KITS.put(KitType.BOOTS, BootsKit.SMALL.getKitId(0));

		FEM_KITS.put(KitType.HAIR, HairKit.PIGTAILS.getKitId(1));
		FEM_KITS.put(KitType.JAW, JawKit.CLEAN_SHAVEN.getKitId(1));
		FEM_KITS.put(KitType.TORSO, TorsoKit.SIMPLE.getKitId(1));
		FEM_KITS.put(KitType.ARMS, ArmsKit.REGULAR.getKitId(1));
		FEM_KITS.put(KitType.LEGS, LegsKit.PLAIN_L.getKitId(1));
		FEM_KITS.put(KitType.HANDS, HandsKit.PLAIN_H.getKitId(1));
		FEM_KITS.put(KitType.BOOTS, BootsKit.SMALL.getKitId(1));
	}

	/**
	 * Produces the fallback kit id for the given slot+gender.
	 * Returns an effective equipment id of 0 if there is no suitable kit id.
	 * If `detectUnknown`, the UI will update, prompting the user to reveal this kit.
	 */
	public int getKit(KitType slot, Integer gender, boolean detectUnknown)
	{
		if (gender == null || slot == null)
		{
			return -FashionManager.KIT_OFFSET;
		}
		Map<KitType, Integer> map = gender == 1 ? FEM_KITS : MASC_KITS;
		int result = map.getOrDefault(slot, -FashionManager.KIT_OFFSET);
		if (detectUnknown && result > 0)
		{
			eventBus.post(new KnownKitChanged(true, slot));
		}
		return result;
	}
}

package eq.uirs.fashionscape.core.randomizer;

import com.google.common.annotations.VisibleForTesting;
import eq.uirs.fashionscape.FashionscapeConfig;
import eq.uirs.fashionscape.colors.ColorScorer;
import eq.uirs.fashionscape.core.Diff;
import eq.uirs.fashionscape.core.Exclusions;
import eq.uirs.fashionscape.core.FashionManager;
import eq.uirs.fashionscape.core.SlotInfo;
import eq.uirs.fashionscape.core.layer.Layers;
import eq.uirs.fashionscape.core.layer.Locks;
import eq.uirs.fashionscape.core.model.ModelInfo;
import eq.uirs.fashionscape.core.utils.ItemSlotUtil;
import eq.uirs.fashionscape.core.utils.KitUtil;
import eq.uirs.fashionscape.core.utils.ListUtil;
import eq.uirs.fashionscape.data.color.ColorType;
import eq.uirs.fashionscape.data.color.Colorable;
import eq.uirs.fashionscape.data.kit.JawIcon;
import eq.uirs.fashionscape.data.kit.JawKit;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.kit.KitType;
import net.runelite.client.game.ItemManager;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = {@Inject})
public class Randomizer
{
	private final Layers layers;
	private final Locks locks;
	private final FashionscapeConfig config;
	private final ColorScorer colorScorer;
	private final Client client;
	private final ItemManager itemManager;
	private final Exclusions exclusions;

	private final Map<KitType, List<SlotInfo>> slotToItemsMemo = new HashMap<>();
	private final Random random = new Random();

	@VisibleForTesting
	void setRandomSeed(long seed)
	{
		random.setSeed(seed);
	}

	public Diff shuffle()
	{
		if (slotToItemsMemo.isEmpty())
		{
			repopulateMemo();
		}

		RandomizerIntelligence intelligence = config.randomizerIntelligence();
		if (intelligence != RandomizerIntelligence.NONE)
		{
			computeLockedColorScores();
		}
		Diff diff = Diff.empty();
		// first, try to occupy all unlocked slots with items
		List<SlotInfo> slottedItems = findItems();
		for (SlotInfo item : slottedItems)
		{
			diff = Diff.merge(layers.set(item.getSlot(), item, false), diff);
		}

		// next, try to occupy remaining slots with random kits (no color scoring since they're recolor-able)
		List<SlotInfo> slottedKits = findKits(slottedItems);
		for (SlotInfo kit : slottedKits)
		{
			diff = Diff.merge(layers.set(kit.getSlot(), kit, false), diff);
		}

		// find the icon that most closely matches on color
		JawIcon icon = findIcon();
		if (icon != null)
		{
			diff = Diff.merge(layers.setIcon(icon, false), diff);
		}

		// lastly, shuffle the player's base model colors
		Map<ColorType, Colorable> colors = findColors();
		for (Map.Entry<ColorType, Colorable> entry : colors.entrySet())
		{
			ColorType colorType = entry.getKey();
			Colorable color = entry.getValue();
			diff = Diff.merge(layers.setColor(colorType, color.getColorId(colorType), false), diff);
		}
		return diff;
	}

	public void repopulateMemo()
	{
		slotToItemsMemo.clear();
		Set<Integer> skips = exclusions.getAll();
		for (int i = 0; i < client.getItemCount(); i++)
		{
			int canonical = itemManager.canonicalize(i);
			// can skip banknote/placeholder items since the canonical version will come up eventually
			if (i != canonical || skips.contains(canonical))
			{
				continue;
			}
			ItemComposition itemComposition = itemManager.getItemComposition(i);
			int itemId = itemComposition.getId();
			KitType slot = ItemSlotUtil.getSlot(itemId, itemManager);
			if (slot == null)
			{
				continue;
			}
			SlotInfo slotInfo = SlotInfo.lookUp(itemId + FashionManager.ITEM_OFFSET, slot);
			List<SlotInfo> itemsInSlot = slotToItemsMemo.getOrDefault(slot, new ArrayList<>());
			itemsInSlot.add(slotInfo);
			slotToItemsMemo.put(slot, itemsInSlot);
		}
	}

	private void computeLockedColorScores()
	{
		ModelInfo info = layers.getVirtualModels();
		Map<KitType, Integer> lockedItems = info.getItems().getAll().values().stream()
			.filter(i -> locks.contains(i.getSlot()))
			.collect(Collectors.toMap(SlotInfo::getSlot, SlotInfo::getItemId));
		if (locks.isIcon() && info.getIcon() != null && info.getIcon() != JawIcon.NOTHING)
		{
			// consider only the icon part of the model, not the built-in facial hair
			Integer iconItemId = JawKit.NO_JAW.getIconItemId(info.getIcon());
			if (iconItemId != null)
			{
				lockedItems.put(KitType.JAW, iconItemId);
			}
		}
		Map<ColorType, Colorable> lockedColors = info.getColors().getAllColorable().entrySet().stream()
			.filter(e -> locks.getColor(e.getKey()))
			.collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
		colorScorer.setPlayerInfo(lockedItems, lockedColors);
	}

	@VisibleForTesting
	List<SlotInfo> findItems()
	{
		List<KitType> remainingItemSlots = Arrays.stream(KitType.values())
			.filter(s -> !locks.contains(s))
			.collect(Collectors.toList());
		Collections.shuffle(remainingItemSlots, random);
		List<SlotInfo> result = new ArrayList<>();
		RandomizerIntelligence intelligence = config.randomizerIntelligence();
		while (!remainingItemSlots.isEmpty())
		{
			KitType slot = remainingItemSlots.remove(0);
			// skip jaw items, as these are handled later as icons
			if (slot == KitType.JAW)
			{
				continue;
			}
			// items in this slot cannot conflict with locked or already-filled slots
			Set<KitType> remainingSet = new HashSet<>(remainingItemSlots);
			List<SlotInfo> allCandidates = slotToItemsMemo.getOrDefault(slot, new ArrayList<>()).stream()
				.filter(slotInfo -> locks.isAllowed(slot, slotInfo) &&
					remainingSet.containsAll(slotInfo.getHidden()))
				.collect(Collectors.toList());
			if (!allCandidates.isEmpty())
			{
				List<SlotInfo> candidates = ListUtil.takeRandomSample(allCandidates, intelligence.getDepth(), random);
				int multiplier = intelligence == RandomizerIntelligence.CURSED ? -1 : 1;
				SlotInfo bestMatch = candidates.stream()
					.max(Comparator.comparingDouble(c -> multiplier * colorScorer.score(c.getItemId(), c.getSlot())))
					.orElse(candidates.get(0));
				result.add(bestMatch);
				// also remove slots that the match hides
				bestMatch.getHidden().forEach(remainingItemSlots::remove);
				colorScorer.addPlayerInfo(bestMatch.getSlot(), bestMatch.getItemId());
			}
		}
		return result;
	}

	@VisibleForTesting
	List<SlotInfo> findKits(List<SlotInfo> existingItems)
	{
		List<SlotInfo> result = new ArrayList<>();
		Integer gender = layers.getGender();
		if (gender != null && !config.excludeBaseModels())
		{
			// check locks and items from last step to ensure kit model can be shown
			List<KitType> remainingKitSlots = Arrays.stream(KitType.values())
				// kit id doesn't matter, just need to check if kit is allowed for current locks
				.filter(slot -> locks.isAllowed(slot, SlotInfo.kit(0, slot)) &&
					existingItems.stream().noneMatch(item -> item.getSlot() == slot || item.hides(slot)))
				.collect(Collectors.toList());
			Collections.shuffle(remainingKitSlots, random);
			while (!remainingKitSlots.isEmpty())
			{
				KitType slot = remainingKitSlots.remove(0);
				// only consider kits applicable to current gender
				List<SlotInfo> candidates = KitUtil.KIT_TYPE_TO_KITS.getOrDefault(slot, new ArrayList<>()).stream()
					.filter(k -> !k.isHidden() && k.getKitId(gender) != null && k != JawKit.NO_JAW)
					.map(k -> SlotInfo.kit(k, gender))
					.collect(Collectors.toList());
				if (!candidates.isEmpty())
				{
					result.add(candidates.get(random.nextInt(candidates.size())));
				}
			}
		}
		return result;
	}

	@VisibleForTesting
	JawIcon findIcon()
	{
		if (locks.isIcon() || config.excludeBaseModels())
		{
			return null;
		}
		JawIcon icon = JawIcon.NOTHING;
		List<JawIcon> icons = Arrays.asList(JawIcon.values());
		// score colors if intelligence is not minimal
		RandomizerIntelligence intelligence = config.randomizerIntelligence();
		if (intelligence != RandomizerIntelligence.NONE && intelligence != RandomizerIntelligence.CURSED)
		{
			Map<JawIcon, Double> scores = icons.stream()
				.collect(Collectors.toMap(i -> i, i -> {
					Integer itemId = JawKit.NO_JAW.getIconItemId(i);
					return itemId != null ? colorScorer.score(itemId, null) : 0;
				}));
			// use icon if >75% match
			icon = scores.entrySet().stream()
				.filter(e -> e.getValue() > 0.75)
				.max(Comparator.comparingDouble(Map.Entry::getValue))
				.map(Map.Entry::getKey)
				.orElse(JawIcon.NOTHING);
		}
		else if (random.nextDouble() > 0.33)
		{
			// since there aren't many icons, just prefer not showing one most of the time
			icon = icons.get(random.nextInt(icons.size()));
		}
		return icon;
	}

	@VisibleForTesting
	Map<ColorType, Colorable> findColors()
	{
		Map<ColorType, Colorable> result = new HashMap<>();
		if (config.excludeBaseModels())
		{
			return result;
		}
		RandomizerIntelligence intelligence = config.randomizerIntelligence();
		for (ColorType colorType : ColorType.values())
		{
			if (locks.getColor(colorType))
			{
				continue;
			}
			List<Colorable> colorables = Arrays.asList(colorType.getColorables().clone());
			Collections.shuffle(colorables, random);
			int limit;
			switch (intelligence)
			{
				case LOW:
					limit = Math.max(1, colorables.size() / 4);
					break;
				case MODERATE:
				case CURSED:
					limit = Math.max(1, colorables.size() / 2);
					break;
				case HIGH:
					limit = colorables.size();
					break;
				default:
					limit = 1;
			}
			int multiplier = intelligence == RandomizerIntelligence.CURSED ? -1 : 1;
			Colorable best = colorables.stream()
				.limit(limit)
				.max(Comparator.comparingDouble(c -> colorScorer.score(c, colorType) * multiplier))
				.orElse(colorables.get(0));
			result.put(colorType, best);
			colorScorer.addPlayerColor(colorType, best);
		}
		return result;
	}
}

package eq.uirs.fashionscape.core.randomizer;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Determines the size of the queue for scoring the "best" matched item via randomizer request
 */
@Getter
@RequiredArgsConstructor
public enum RandomizerIntelligence
{
	NONE(1),
	LOW(10),
	MODERATE(50),
	HIGH(100),
	CURSED(50); // prefers mismatched colors

	private final int depth;
}

package eq.uirs.fashionscape.core;

import com.google.gson.reflect.TypeToken;
import eq.uirs.fashionscape.FashionscapeConfig;
import eq.uirs.fashionscape.core.event.ColorChanged;
import eq.uirs.fashionscape.core.event.ColorLockChanged;
import eq.uirs.fashionscape.core.event.IconChanged;
import eq.uirs.fashionscape.core.event.IconLockChanged;
import eq.uirs.fashionscape.core.event.ItemChanged;
import eq.uirs.fashionscape.core.event.KitChanged;
import eq.uirs.fashionscape.core.event.LockChanged;
import eq.uirs.fashionscape.core.layer.Layers;
import eq.uirs.fashionscape.core.layer.Locks;
import eq.uirs.fashionscape.core.layer.ModelType;
import eq.uirs.fashionscape.core.model.ModelInfo;
import eq.uirs.fashionscape.core.utils.ConfigSerializer;
import eq.uirs.fashionscape.data.color.ColorType;
import eq.uirs.fashionscape.data.kit.JawIcon;
import java.lang.reflect.Type;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.Future;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;
import javax.annotation.Nonnull;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.kit.KitType;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;

/**
 * Manages the plugin's hidden configs
 */
@Singleton
@Slf4j
public class ConfigHelper
{
	//@formatter:off
	private static final Type EQUIPMENT_INFO_TYPE = new TypeToken<HashMap<KitType, SlotInfo>>(){}.getType();
	private static final Type COLORS_TYPE = new TypeToken<HashMap<Integer, Integer>>(){}.getType();
	private static final Type LOCKS_TYPE = new TypeToken<HashMap<KitType, LockStatus>>(){}.getType();
	private static final Type COLOR_LOCKS_TYPE = new TypeToken<HashMap<ColorType, Boolean>>(){}.getType();
	private static final Type KIT_IDS_TYPE = new TypeToken<HashMap<KitType, Integer>>(){}.getType();
	//@formatter:on
	private static final int DEBOUNCE_DELAY_MS = 500;

	@Inject
	private Client client;

	@Inject
	private FashionscapeConfig config;

	@Inject
	private ConfigSerializer configSerializer;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private Layers layers;

	@Inject
	private Locks locks;

	// should only load once since config might be behind local state.
	// saving is also blocked until this is set, otherwise unread config would get clobbered
	private boolean hasLoadedConfig;

	private Future<?> colorSaveFuture;
	private Future<?> kitsSaveFuture;
	private Future<?> equipSaveFuture;
	private Future<?> iconSaveFuture;
	private Future<?> locksSaveFuture;

	@Subscribe
	public void onColorChanged(ColorChanged e)
	{
		if (e.getModelType() == ModelType.VIRTUAL)
		{
			saveColorConfigDebounced();
		}
	}

	@Subscribe
	public void onIconChanged(IconChanged e)
	{
		if (e.getModelType() == ModelType.VIRTUAL)
		{
			saveIconDebounced();
		}
	}

	@Subscribe
	public void onItemChanged(ItemChanged e)
	{
		if (e.getModelType() == ModelType.VIRTUAL)
		{
			saveEquipmentConfigDebounced();
		}
	}

	@Subscribe
	public void onKitChanged(KitChanged e)
	{
		if (e.getModelType() == ModelType.VIRTUAL)
		{
			saveEquipmentConfigDebounced();
		}
		// need to check game state: don't handle clearing real models on logout
		else if (e.getModelType() == ModelType.REAL && client.getGameState() == GameState.LOGGED_IN)
		{
			saveRealKitsDebounced();
		}
	}

	@Subscribe
	public void onColorLockChanged(ColorLockChanged e)
	{
		saveLocksDebounced();
	}

	@Subscribe
	public void onIconLockChanged(IconLockChanged e)
	{
		saveLocksDebounced();
	}

	@Subscribe
	public void onLockChanged(LockChanged e)
	{
		saveLocksDebounced();
	}

	/**
	 * Reads from global config. Call after listeners are set (i.e., after panels created).
	 * This only needs to be called once after client restart; layers and locks will remain even when plugin shuts down
	 */
	void loadFromConfig()
	{
		if (hasLoadedConfig)
		{
			return;
		}
		hasLoadedConfig = true;
		HashMap<KitType, SlotInfo> equipInfo = safeDeserialize(config.equipmentInfo(), EQUIPMENT_INFO_TYPE, new HashMap<>());

		ColorType[] allColorTypes = ColorType.values();
		Map<Integer, Integer> rawColorIds = safeDeserialize(config.colors(), COLORS_TYPE, new HashMap<>());
		Map<ColorType, Integer> colorIds = rawColorIds.entrySet().stream()
			.collect(Collectors.toMap(e -> allColorTypes[e.getKey()], Map.Entry::getValue));

		Map<KitType, LockStatus> lockStatuses = safeDeserialize(config.locks(), LOCKS_TYPE, new HashMap<>());
		Map<ColorType, Boolean> colorLocks = safeDeserialize(config.colorLocks(), COLOR_LOCKS_TYPE, new HashMap<>());

		Integer iconId = config.icon();
		JawIcon icon = iconId != null ? JawIcon.fromId(config.icon()) : null;

		layers.restore(equipInfo, colorIds, icon);
		locks.restore(lockStatuses, colorLocks, config.iconLocked());
	}

	private <T> T safeDeserialize(byte[] bytes, Type type, T fallback)
	{
		try
		{
			T result = configSerializer.deserialize(bytes, type);
			if (result != null)
			{
				return result;
			}
		}
		catch (Exception e)
		{
			log.error("could not deserialize bad byte array", e);
		}
		return fallback;
	}

	/**
	 * Loads default kits from config. Called during pre-refresh check, on first login and on rsn change
	 */
	void loadRSProfileConfig()
	{
		byte[] realKits = configManager.getRSProfileConfiguration(FashionscapeConfig.GROUP,
			FashionscapeConfig.KEY_REAL_KITS, byte[].class);
		HashMap<KitType, Integer> info = safeDeserialize(realKits, KIT_IDS_TYPE, new HashMap<>());
		layers.restoreFromRSProfile(info);
	}

	// migrates from less detailed equipment ids to full SlotInfo. must be called after external data is fetched
	void migrateEquipmentInfo()
	{
		HashMap<KitType, Integer> legacyEquipment = safeDeserialize(config.legacyEquipment(), KIT_IDS_TYPE, new HashMap<>());
		if (legacyEquipment.isEmpty())
		{
			// force set legacy equipment in case the value can't be deserialized
			config.setLegacyEquipment(configSerializer.serialize(new HashMap<KitType, Integer>()));
			return;
		}
		HashMap<KitType, SlotInfo> newEquipment = new HashMap<>();
		// check items separately (will allow removing redundant 0s)
		List<Map.Entry<KitType, Integer>> itemEquipIds = legacyEquipment.entrySet().stream()
			.filter(e -> e.getValue() >= FashionManager.ITEM_OFFSET)
			.collect(Collectors.toList());
		for (Map.Entry<KitType, Integer> entry : itemEquipIds)
		{
			KitType slot = entry.getKey();
			SlotInfo info = SlotInfo.lookUp(entry.getValue(), slot);
			newEquipment.put(slot, info);
			legacyEquipment.remove(slot);
			info.getHidden().forEach(legacyEquipment::remove);
		}
		// only explicit nothing and kits should remain
		for (Map.Entry<KitType, Integer> entry : legacyEquipment.entrySet())
		{
			KitType slot = entry.getKey();
			SlotInfo info = SlotInfo.lookUp(entry.getValue(), slot);
			newEquipment.put(slot, info);
		}
		config.setEquipmentInfo(configSerializer.serialize(newEquipment));
		config.setLegacyEquipment(configSerializer.serialize(new HashMap<KitType, Integer>()));
	}

	private void saveEquipmentConfigDebounced()
	{
		if (!hasLoadedConfig)
		{
			return;
		}
		equipSaveFuture = withDebounce(equipSaveFuture, () -> {
			ModelInfo models = layers.getVirtualModels();
			HashMap<KitType, SlotInfo> result = new HashMap<>(models.getItems().getAll());
			Map<KitType, SlotInfo> kits = models.getKits().getAll().entrySet().stream()
				.collect(Collectors.toMap(Map.Entry::getKey, (e) -> SlotInfo.kit(e.getValue(), e.getKey())));
			result.putAll(kits);
			config.setEquipmentInfo(configSerializer.serialize(result));
		});
	}

	private void saveIconDebounced()
	{
		if (!hasLoadedConfig)
		{
			return;
		}
		iconSaveFuture = withDebounce(iconSaveFuture, () -> {
			JawIcon icon = layers.getVirtualModels().getIcon();
			Integer iconId = icon != null ? icon.getId() : null;
			config.setIcon(iconId);
		});
	}

	private void saveColorConfigDebounced()
	{
		if (!hasLoadedConfig)
		{
			return;
		}
		colorSaveFuture = withDebounce(colorSaveFuture, () -> {
			Map<Integer, Integer> rawColors = layers.getVirtualModels().getColors().getAll().entrySet().stream()
				.collect(Collectors.toMap(e -> e.getKey().ordinal(), Map.Entry::getValue));
			HashMap<Integer, Integer> colors = new HashMap<>(rawColors);
			config.setColors(configSerializer.serialize(colors));
		});
	}

	private void saveRealKitsDebounced()
	{
		kitsSaveFuture = withDebounce(kitsSaveFuture, () -> {
			HashMap<KitType, Integer> result = new HashMap<>(layers.getRealModels().getKits().getAll());
			byte[] bytes = configSerializer.serialize(result);
			configManager.setRSProfileConfiguration(FashionscapeConfig.GROUP, FashionscapeConfig.KEY_REAL_KITS, bytes);
		});
	}

	private void saveLocksDebounced()
	{
		if (!hasLoadedConfig)
		{
			return;
		}
		locksSaveFuture = withDebounce(locksSaveFuture, () -> {
			//noinspection DataFlowIssue (filter ensures non-null)
			Map<KitType, LockStatus> lockedSlots = Arrays.stream(KitType.values())
				.filter(slot -> locks.get(slot) != null)
				.collect(Collectors.toMap(slot -> slot, slot -> locks.get(slot)));
			byte[] locksBytes = configSerializer.serialize(new HashMap<>(lockedSlots));
			config.setLocks(locksBytes);
			Map<ColorType, Boolean> colorLocks = Arrays.stream(ColorType.values())
				.collect(Collectors.toMap(type -> type, locks::getColor));
			byte[] colorBytes = configSerializer.serialize(new HashMap<>(colorLocks));
			config.setColorLocks(colorBytes);
			config.setIconLocked(locks.isIcon());
		});
	}

	private Future<?> withDebounce(Future<?> running, @Nonnull Runnable block)
	{
		if (running != null)
		{
			running.cancel(false);
		}
		return executor.schedule(block, DEBOUNCE_DELAY_MS, TimeUnit.MILLISECONDS);
	}
}

