/**
 * State for each equipment slot, which can contain an item, "nothing", or be unset.
 * Kit ids are stored separately (in Kits class) because of potential overlap.
 */
@Data
@Getter(AccessLevel.PRIVATE)
public class Items
{
	private final ModelType modelType;
	private final EventBus eventBus;
	private final Map<KitType, SlotInfo> value = new HashMap<>();

	public ImmutableMap<KitType, SlotInfo> getAll()
	{
		return ImmutableMap.copyOf(value);
	}

	@Nullable
	public SlotInfo get(KitType slot)
	{
		return value.get(slot);
	}

	public boolean containsKey(KitType slot)
	{
		return get(slot) != null;
	}

	public SlotInfo remove(KitType slot)
	{
		return put(slot, null);
	}

	@Nullable
	public SlotInfo put(KitType slot, @Nullable SlotInfo info)
	{
		SlotInfo oldInfo = info == null ? value.remove(slot) : value.put(slot, info);
		eventBus.post(new ItemChanged(slot, modelType, info));
		return oldInfo;
	}

	public void putAll(Map<KitType, SlotInfo> other)
	{
		other.forEach(this::put);
	}

	public boolean isEmpty()
	{
		return value.isEmpty();
	}

	public void clear()
	{
		Set<KitType> removes = new HashSet<>(value.keySet());
		removes.forEach(this::remove);
	}
}

package eq.uirs.fashionscape.core.model;

import com.google.common.collect.ImmutableMap;
import eq.uirs.fashionscape.core.FashionManager;
import eq.uirs.fashionscape.core.event.KitChanged;
import eq.uirs.fashionscape.core.layer.ModelType;
import eq.uirs.fashionscape.core.utils.KitUtil;
import eq.uirs.fashionscape.data.kit.JawIcon;
import eq.uirs.fashionscape.data.kit.JawKit;
import eq.uirs.fashionscape.data.kit.Kit;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.stream.Collectors;
import javax.annotation.Nullable;
import lombok.AccessLevel;
import lombok.Data;
import lombok.Setter;
import net.runelite.api.kit.KitType;
import net.runelite.client.eventbus.EventBus;

/**
 * State for each built-in kit model on the player.
 * Values are kit ids. Zero is not allowed (Items class handles "nothing").
 * These may remain in place even if any equipped items obscure the models, since items take priority.
 */
@Data
@Setter(AccessLevel.PRIVATE)
public class Kits
{
	private final ModelType modelType;
	private final EventBus eventBus;
	// values are kit ids
	private final Map<KitType, Integer> value = new HashMap<>();

	public ImmutableMap<KitType, Integer> getAll()
	{
		return ImmutableMap.copyOf(value);
	}

	public Integer get(KitType slot)
	{
		return value.get(slot);
	}

	public boolean containsKey(KitType slot)
	{
		return get(slot) != null;
	}

	public Integer remove(KitType slot)
	{
		return put(slot, null);
	}

	public Integer put(KitType slot, Integer kitId)
	{
		Integer oldId = kitId == null ? value.remove(slot) : value.put(slot, kitId);
		eventBus.post(new KitChanged(slot, modelType, kitId));
		return oldId;
	}

	public boolean isEmpty()
	{
		return value.isEmpty();
	}

	public void clear()
	{
		Set<KitType> removes = new HashSet<>(value.keySet());
		removes.forEach(this::remove);
	}

	/**
	 * Replaces any stored kit ids with new ones for the given gender.
	 * If `destructive`, the wrongly-gendered kits will be removed.
	 * Otherwise, will attempt to replace the kit id with an analog kit id.
	 */
	public void setGender(int gender, boolean destructive)
	{
		for (KitType slot : KitType.values())
		{
			replaceGenderedKit(slot, gender, destructive);
		}
	}

	private void replaceGenderedKit(KitType slot, int newGender, boolean destructive)
	{
		Integer kitId = get(slot);
		if (kitId != null)
		{
			// check whether the kit is already correct for this gender
			Kit kit = KitUtil.KIT_ID_TO_KIT.get(kitId);
			if (kit != null && Objects.equals(kit.getKitId(newGender), kitId))
			{
				return;
			}
		}
		else
		{
			// nothing in the slot -> no need to replace
			return;
		}
		if (destructive)
		{
			put(slot, null);
		}
		else
		{
			Kit kit = KitUtil.KIT_ID_TO_KIT.get(kitId);
			Integer newKitId = kit != null ? kit.getKitId(newGender) : null;
			put(slot, newKitId);
		}
	}

	/**
	 * Returns map of equipment ids for each slot. The jaw slot will combine with the icon argument.
	 */
	public Map<KitType, Integer> computeEquipment(@Nullable JawIcon icon)
	{
		return value.entrySet().stream()
			.collect(Collectors.toMap(Map.Entry::getKey, e -> {
				KitType slot = e.getKey();
				Integer kitId = e.getValue();
				return slot == KitType.JAW ? JawKit.getEquipmentId(kitId, icon) : kitId + FashionManager.KIT_OFFSET;
			}));
	}
}

package eq.uirs.fashionscape.core.model;

import com.google.common.collect.ImmutableMap;
import eq.uirs.fashionscape.core.event.ColorChanged;
import eq.uirs.fashionscape.core.layer.ModelType;
import eq.uirs.fashionscape.data.color.BootsColor;
import eq.uirs.fashionscape.data.color.ClothingColor;
import eq.uirs.fashionscape.data.color.ColorType;
import eq.uirs.fashionscape.data.color.Colorable;
import eq.uirs.fashionscape.data.color.HairColor;
import eq.uirs.fashionscape.data.color.SkinColor;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.function.BiFunction;
import java.util.stream.Collectors;
import lombok.AccessLevel;
import lombok.Data;
import lombok.Setter;
import net.runelite.client.eventbus.EventBus;

/**
 * State for each color-able model on the player.
 */
@Data
@Setter(AccessLevel.PRIVATE)
public class Colors
{
	private final ModelType modelType;
	private final EventBus eventBus;
	// values are color ids, not rgb ints; see Colorable interface
	private final Map<ColorType, Integer> value = new HashMap<>();

	public ImmutableMap<ColorType, Integer> getAll()
	{
		return ImmutableMap.copyOf(value);
	}

	public Map<ColorType, Colorable> getAllColorable()
	{
		BiFunction<ColorType, Integer, Colorable> getColor = (type, id) -> {
			switch (type)
			{
				case HAIR:
					return HairColor.fromId(id);
				case TORSO:
					return ClothingColor.fromTorsoId(id);
				case LEGS:
					return ClothingColor.fromLegsId(id);
				case BOOTS:
					return BootsColor.fromId(id);
				case SKIN:
					return SkinColor.fromId(id);
			}
			return null;
		};
		return Arrays.stream(ColorType.values())
			.filter(value::containsKey)
			.collect(Collectors.toMap(t -> t, t -> getColor.apply(t, get(t))));
	}

	public Integer get(ColorType slot)
	{
		return value.get(slot);
	}

	public Integer remove(ColorType slot)
	{
		return put(slot, null);
	}

	public Integer put(ColorType slot, Integer colorId)
	{
		Integer oldId = colorId == null ? value.remove(slot) : value.put(slot, colorId);
		eventBus.post(new ColorChanged(slot, modelType, colorId));
		return oldId;
	}

	public void putAll(Map<ColorType, Integer> other)
	{
		other.forEach(this::put);
	}

	public boolean isEmpty()
	{
		return value.isEmpty();
	}

	public void clear()
	{
		Set<ColorType> removes = new HashSet<>(value.keySet());
		removes.forEach(this::remove);
	}
}

