import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;

/**
 * Because fashionscape only operates on non-transformed players,
 * calls to get players' compositions is wrapped in this class,
 * which discards compositions if there's a non-default TransformedNpcId.
 */
@Singleton
@Slf4j
@RequiredArgsConstructor(onConstructor_ = {@Inject})
public class CompositionHelper
{
	private final Client client;

	@Nullable
	public PlayerComposition getLocal()
	{
		return get(client.getLocalPlayer());
	}

	public PlayerComposition get(@Nullable Player player)
	{
		if (player == null)
		{
			return null;
		}
		PlayerComposition composition = player.getPlayerComposition();
		if (composition == null || composition.getTransformedNpcId() != -1)
		{
			return null;
		}
		return composition;
	}
}

package eq.uirs.fashionscape.core;

import com.google.common.collect.ImmutableSet;
import eq.uirs.fashionscape.FashionscapeConfig;
import eq.uirs.fashionscape.core.utils.ItemSlotUtil;
import eq.uirs.fashionscape.data.MiscData;
import eq.uirs.fashionscape.data.kit.BootsKit;
import eq.uirs.fashionscape.remote.RemoteData;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.kit.KitType;
import net.runelite.client.game.ItemManager;

/**
 * Builds sets of items to filter out (glitched items, duplicates, potentially members-only)
 */
@Singleton
@Slf4j
@RequiredArgsConstructor(onConstructor_ = {@Inject})
public class Exclusions
{
	private static final Pattern PAREN_REPLACE = Pattern.compile("\\(.*\\)");
	/**
	 * kit ids of boot-slot equipment that, when detected in-game, will disable the boots, weapon and shield slots
	 */
	public static final Set<Integer> DISABLE_ANIM_BOOTS = ImmutableSet.of(BootsKit.MINECART.getKitId(0),
		BootsKit.MINECART.getKitId(1));

	private final Set<Integer> bad = new HashSet<>();
	private final Set<Integer> dupes = new HashSet<>();
	private final Set<Integer> members = new HashSet<>();

	private final Client client;
	private final ItemManager itemManager;
	private final FashionscapeConfig config;
	private final IdleAnimations idleAnimations;

	@Value
	private static class ItemDupeData
	{
		int modelId;
		short[] colorsToReplace;
		short[] texturesToReplace;
		String strippedName;
	}

	/**
	 * populates excluded items after remote data is fetched.
	 * @return false if client doesn't have items populated
	 */
	public boolean loadAll()
	{
		// item count will be 0 if cache is not ready yet
		if (client.getItemCount() == 0)
		{
			return false;
		}
		// plugin checks for the presence of this before calling
		MiscData miscData = RemoteData.MISC_DATA;
		bad.addAll(miscData.badItemIds);
		miscData.badItemRanges.forEach(range -> {
			IntStream.range(range.startInclusive, range.endInclusive + 1)
				.forEach(bad::add);
		});
		List<Pattern> badRegexes = miscData.badItemRegexes.stream()
			.map(Pattern::compile)
			.collect(Collectors.toList());
		Set<ItemDupeData> itemUniques = new HashSet<>();
		for (int i = 0; i < client.getItemCount(); i++)
		{
			int canonical = itemManager.canonicalize(i);
			if (i != canonical || bad.contains(canonical))
			{
				continue;
			}
			KitType slot = ItemSlotUtil.getSlot(i, itemManager);
			if (slot != null)
			{
				ItemComposition itemComposition = itemManager.getItemComposition(canonical);
				if (slot == KitType.WEAPON)
				{
					idleAnimations.queue(itemComposition);
				}
				if (itemComposition.isMembers())
				{
					members.add(i);
				}
				String itemName = itemComposition.getMembersName().toLowerCase();
				if (miscData.badItemNames.contains(itemName))
				{
					bad.add(i);
					continue;
				}
				boolean foundBadContains = miscData.badItemContains.stream()
					.anyMatch(itemName::contains);
				if (foundBadContains)
				{
					bad.add(i);
					continue;
				}
				boolean foundBadRegex = badRegexes.stream()
					.anyMatch(regex -> regex.matcher(itemName).find());
				if (foundBadRegex)
				{
					bad.add(i);
					continue;
				}
				ItemDupeData itemDupeData = new ItemDupeData(
					itemComposition.getInventoryModel(),
					itemComposition.getColorToReplaceWith(),
					itemComposition.getTextureToReplaceWith(),
					stripName(itemName)
				);
				if (itemUniques.contains(itemDupeData))
				{
					dupes.add(canonical);
					continue;
				}
				itemUniques.add(itemDupeData);
			}
		}
		return true;
	}

	public Set<Integer> getAll()
	{
		Set<Integer> result = new HashSet<>(bad);
		result.addAll(dupes);
		if (config.excludeMembersItems())
		{
			result.addAll(members);
		}
		return result;
	}

	private String stripName(String name)
	{
		String noParens = PAREN_REPLACE.matcher(name).replaceAll("");
		return noParens.replaceAll("[^A-Za-z]+", "");
	}
}

package eq.uirs.fashionscape.core;

import eq.uirs.fashionscape.data.ItemSlotInfo;
import eq.uirs.fashionscape.data.kit.Kit;
import eq.uirs.fashionscape.remote.RemoteData;
import java.io.Serializable;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import lombok.NonNull;
import lombok.Value;
import net.runelite.api.kit.KitType;

/**
 * Collected data about the occupant of a single slot.
 * An instance may be an item, a kit, or nothing.
 */
@Value
public class SlotInfo implements Serializable
{
	int equipmentId;
	@NonNull
	KitType slot;
	// for items: hidden info is determined from wearpos values from cache
	@NonNull
	Set<KitType> hidden;

	public static SlotInfo item(int itemId, KitType slot, KitType... hidden)
	{
		return new SlotInfo(itemId + FashionManager.ITEM_OFFSET, slot,
			Arrays.stream(hidden).collect(Collectors.toSet()));
	}

	public static SlotInfo kit(Kit k, int gender)
	{
		return kit(k.getKitId(gender), k.getKitType());
	}

	public static SlotInfo kit(int kitId, KitType slot)
	{
		return new SlotInfo(kitId + FashionManager.KIT_OFFSET, slot, new HashSet<>());
	}

	public static SlotInfo nothing(KitType slot)
	{
		return new SlotInfo(0, slot, new HashSet<>());
	}

	/**
	 * Most general way to create new SlotInfo.
	 * Uses ExternalData to look up hidden slots in the case of items.
	 * Ensure that jaw slot items are converted to kit ids before calling, and that icon is handled separately.
	 */
	public static SlotInfo lookUp(int equipId, KitType slot)
	{
		if (equipId <= FashionManager.KIT_OFFSET)
		{
			return nothing(slot);
		}
		else if (equipId <= FashionManager.ITEM_OFFSET)
		{
			return kit(equipId - FashionManager.KIT_OFFSET, slot);
		}
		else
		{
			int itemId = equipId - FashionManager.ITEM_OFFSET;
			Map<Integer, ItemSlotInfo> idToSlotInfo = RemoteData.ITEM_ID_TO_INFO;
			ItemSlotInfo info = idToSlotInfo.get(itemId);
			if (info == null || info.hidden0 == null && info.hidden1 == null)
			{
				return item(itemId, slot);
			}
			KitType[] types = KitType.values();
			Set<KitType> hidden = new HashSet<>();
			if (info.hidden0 != null)
			{
				hidden.add(types[info.hidden0]);
			}
			if (info.hidden1 != null)
			{
				hidden.add(types[info.hidden1]);
			}
			return new SlotInfo(itemId + FashionManager.ITEM_OFFSET, slot, hidden);
		}
	}

	public int getItemId()
	{
		return equipmentId - FashionManager.ITEM_OFFSET;
	}

	public int getKitId()
	{
		return equipmentId - FashionManager.KIT_OFFSET;
	}

	public boolean isItem()
	{
		return equipmentId >= FashionManager.ITEM_OFFSET;
	}

	public boolean isKit()
	{
		return equipmentId >= FashionManager.KIT_OFFSET && equipmentId < FashionManager.ITEM_OFFSET;
	}

	public boolean isNothing()
	{
		return equipmentId == 0;
	}

	// whether the given slot is hidden while this model is active
	public boolean hides(KitType kit)
	{
		return hidden.contains(kit);
	}

	public Map<KitType, Integer> computeEquipment()
	{
		Map<KitType, Integer> result = new HashMap<>();
		result.put(slot, equipmentId);
		hidden.forEach(s -> result.put(s, 0));
		return result;
	}
}

package eq.uirs.fashionscape.core.layer;

import com.google.common.collect.Sets;
import eq.uirs.fashionscape.core.LockStatus;
import eq.uirs.fashionscape.core.SlotInfo;
import eq.uirs.fashionscape.core.event.ColorLockChanged;
import eq.uirs.fashionscape.core.event.IconLockChanged;
import eq.uirs.fashionscape.core.event.LockChanged;
import eq.uirs.fashionscape.core.model.Items;
import eq.uirs.fashionscape.data.color.ColorType;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.NonNull;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.kit.KitType;
import net.runelite.client.eventbus.EventBus;

/**
 * Stores info about item+kit slots, color ids, and jaw icons that the user does not want to change.
 */
@Singleton
@Slf4j
@RequiredArgsConstructor(onConstructor_ = {@Inject})
public class Locks
{
	private final Layers layers;
	private final EventBus eventBus;

	private final Map<KitType, LockStatus> slots = new HashMap<>();
	private final Set<ColorType> colors = new HashSet<>();
	@Getter
	private boolean icon = false;

	@Nullable
	public LockStatus get(KitType slot)
	{
		return slots.get(slot);
	}

	/**
	 * Whether the slot is locked on a non-null LockStatus.
	 * Use `get` if the exact status is needed.
	 */
	public boolean contains(KitType slot)
	{
		return get(slot) != null;
	}

	/**
	 * Whether the color for a player model section is locked
	 */
	public boolean getColor(ColorType type)
	{
		return colors.contains(type);
	}

	public void set(KitType slot, @Nullable LockStatus value)
	{
		if (value == null)
		{
			slots.remove(slot);
		}
		else
		{
			slots.put(slot, value);
		}
		eventBus.post(new LockChanged(slot, value));
	}

	public void set(ColorType color, boolean locked)
	{
		if (locked)
		{
			colors.add(color);
		}
		else
		{
			colors.remove(color);
		}
		eventBus.post(new ColorLockChanged(color, locked));
	}

	public void setIcon(boolean locked)
	{
		icon = locked;
		eventBus.post(new IconLockChanged(locked));
	}

	public void toggle(KitType slot, @NonNull LockStatus type)
	{
		LockStatus old = slots.get(slot);
		// if slot wasn't locked (or going from item -> kit+item), add to locks. otherwise unlock
		if (old == null || (old == LockStatus.ITEM && type == LockStatus.ALL))
		{
			set(slot, type);
		}
		else
		{
			set(slot, null);
		}
	}

	public void toggle(ColorType color)
	{
		set(color, !getColor(color));
	}

	public void toggleIcon()
	{
		setIcon(!icon);
	}

	public void clear()
	{
		new HashSet<>(slots.keySet()).forEach(k -> set(k, null));
		new HashSet<>(colors).forEach(c -> set(c, false));
		setIcon(false);
	}

	public boolean isAllowed(KitType slot, @Nullable SlotInfo info)
	{
		return conflictingSlots(slot, info).isEmpty();
	}

	/**
	 * Produces a set of slots which are in "conflict" with the arguments, i.e., the current state of the user's
	 * locks prevent this change from happening. If no conflicts exist, returns an empty set.
	 */
	@Nonnull
	public Set<KitType> conflictingSlots(KitType slot, @Nullable SlotInfo info)
	{
		Set<KitType> conflicts = new HashSet<>();
		Items items = layers.getVirtualModels().getItems();
		SlotInfo existing = items.get(slot);
		// 1. is the slot locked?
		LockStatus status = slots.get(slot);
		if (status != null)
		{
			// lock will prevent if this change involves items or if both kits+items are locked
			boolean changingItems = existing != null && existing.isItem() || info != null && info.isItem();
			if (status == LockStatus.ALL || changingItems)
			{
				conflicts.add(slot);
			}
		}
		// 2. could a locked item in another slot be forcibly hiding this slot, preventing any change?
		// e.g., if locked on a full helm item, can't change hair/jaw
		// note that placing "nothing" in this example would still not be allowable
		items.getAll().values().stream()
			.filter(s -> s.getSlot() != slot && contains(s.getSlot()) && s.hides(slot))
			.map(SlotInfo::getSlot)
			.forEach(conflicts::add);
		// 3. will this change hide or un-hide any other locked slots as a side effect?
		// e.g., if hair is locked, any head slot change must keep hair shown/hidden as it was before.
		// if multiple items are removed by a single slot change, before/after must still match on hidden+locked slots.
		Set<KitType> locked = slots.keySet();
		Set<KitType> incHidden = info != null ? info.getHidden() : new HashSet<>();
		Set<KitType> outHidden = existing != null ? existing.getHidden() : new HashSet<>();
		Set<KitType> hiddenLockedIncoming = new HashSet<>(Sets.intersection(incHidden, locked));
		Set<KitType> hiddenLockedOutgoing = new HashSet<>(Sets.intersection(outHidden, locked));
		// find all unlocked items which the incoming item hides
		List<SlotInfo> outIncHides = incHidden.stream()
			.filter(s -> !contains(s) && items.containsKey(s))
			.map(items::get)
			.collect(Collectors.toList());
		// find all unlocked items that either hide incoming slot or share hidden slots with incoming item
		// note: sharing hidden slots is conflicting because these items often visually occupy the slots they hide
		List<SlotInfo> outHidesInc = items.getAll().values().stream()
			.filter(i -> !contains(i.getSlot()) &&
				(i.hides(slot) || !Sets.intersection(i.getHidden(), incHidden).isEmpty()))
			.collect(Collectors.toList());
		// all slots hidden+locked by these items are added to "outgoing" set
		Stream.concat(outIncHides.stream(), outHidesInc.stream())
			.flatMap(i -> Sets.intersection(i.getHidden(), locked).stream())
			.forEach(hiddenLockedOutgoing::add);
		// any slot in one set but not the other is considered to be in conflict
		conflicts.addAll(Sets.symmetricDifference(hiddenLockedIncoming, hiddenLockedOutgoing));
		return conflicts;
	}

	// restores previously-set locks from config
	public void restore(Map<KitType, LockStatus> slots, Map<ColorType, Boolean> colors, boolean icon)
	{
		for (KitType slot : KitType.values())
		{
			set(slot, slots.get(slot));
		}
		for (ColorType type : ColorType.values())
		{
			set(type, Objects.equals(true, colors.get(type)));
		}
		setIcon(icon);
	}
}

package eq.uirs.fashionscape.core.layer;

import com.google.common.annotations.VisibleForTesting;
import com.google.common.collect.ImmutableMap;
